27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "member_id")
71	    private String memberId;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private Boolean bulkSignupWarning;
81	
82	    @Column(name = "capacity_warning")
83	    private Boolean capacityWarning;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    @Column(name = "postcode")
89	    private String postcode;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @Column(name = "membership_level_cap")
95	    private Integer membershipLevelCap;
96	
97	    @Column(name = "deleted", nullable = false)
98	    private boolean deleted;
99	
100	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
101	    private Set<Pet> pets;
102	
103	    public String getTitle() {
104	        return this.title;
105	    }
106	
107	    public void setTitle(String title) {
108	        this.title = title;
109	    }
110	
111	    public String getAddress() {
112	        return this.address;
113	    }
114	
115	    public void setAddress(String address) {
116	        this.address = address;
117	    }
118	
119	    /**
120	     * The first line of this owner's structured postal address, or {@code null} when the owner was
121	     * created with only the flat {@link #getAddress() address}. Preferred over the flat address when
122	     * present; see {@link #getAddress()} for the composed form.
123	     */
124	    public String getAddressLine1() {
125	        return this.addressLine1;
126	    }
127	
128	    public void setAddressLine1(String addressLine1) {
129	        this.addressLine1 = addressLine1;
130	    }
131	
132	    /**
133	     * The optional second line of this owner's structured postal address, or {@code null} when none
134	     * was supplied. When present it is appended to {@link #getAddressLine1() addressLine1} in the
135	     * composed {@link #getAddress() address}.
136	     */
137	    public String getAddressLine2() {
138	        return this.addressLine2;
139	    }
140	
141	    public void setAddressLine2(String addressLine2) {
142	        this.addressLine2 = addressLine2;
143	    }
144	
145	    public String getCity() {
146	        return this.city;
147	    }
148	
149	    public void setCity(String city) {
150	        this.city = city;
151	    }
152	
153	    public String getTelephone() {
154	        return this.telephone;
155	    }
156	
157	    public void setTelephone(String telephone) {
158	        this.telephone = telephone;
159	    }
160	
161	    /**
162	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
163	     * as the calling code, a space, then the national digits grouped in threes, e.g.
164	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
165	     */
166	    @Transient
167	    public String getTelephoneDisplay() {
168	        return TelephoneFormatter.toDisplay(this.telephone);
169	    }
170	
171	    public String getEmail() {
172	        return this.email;
173	    }
174	
175	    public void setEmail(String email) {
176	        this.email = email;
177	    }
178	
179	    public LocalDate getRegistrationDate() {
180	        return this.registrationDate;
181	    }
182	
183	    public void setRegistrationDate(LocalDate registrationDate) {
184	        this.registrationDate = registrationDate;
185	    }
186	
187	    /**
188	     * Return this owner's fiscal year, formatted {@code FY<YY>}, derived from the (business-day
189	     * adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is named by the
190	     * calendar year in which it ends. {@code null} when no registration date is known.
191	     */
192	    @Transient
193	    public String getFiscalYear() {
194	        return this.registrationDate == null ? null : FiscalYear.of(this.registrationDate).getLabel();
195	    }
196	
197	    public LocalDate getBirthDate() {
198	        return this.birthDate;
199	    }
200	
201	    public void setBirthDate(LocalDate birthDate) {
202	        this.birthDate = birthDate;
203	    }
204	
205	    /**
206	     * Return this owner's member id, the single identifier formatted
207	     * {@code <REGION><FY><HASH8><CHK>}: the region code, the two-digit fiscal year, the eight
208	     * upper-case hex characters of SHA-256 over the normalized telephone followed by the last name,
209	     * and a single Luhn check digit over the digits of the preceding segments.
210	     */
211	    public String getMemberId() {
212	        return this.memberId;
213	    }
214	
215	    public void setMemberId(String memberId) {
216	        this.memberId = memberId;
217	    }
218	
219	    public String getHouseholdId() {
220	        return this.householdId;
221	    }
222	
223	    public void setHouseholdId(String householdId) {
224	        this.householdId = householdId;
225	    }
226	
227	    public Integer getNamesakeCount() {
228	        return this.namesakeCount;
229	    }
230	
231	    public void setNamesakeCount(Integer namesakeCount) {
232	        this.namesakeCount = namesakeCount;
233	    }
234	
235	    /**
236	     * Whether this owner was created after more than 80 owners had already been registered on the
237	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
238	     */
239	    public Boolean getBulkSignupWarning() {
240	        return this.bulkSignupWarning;
241	    }
242	
243	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
244	        this.bulkSignupWarning = bulkSignupWarning;
245	    }
246	
247	    /**
248	     * Whether this owner's city had already reached the capacity-warning band (at least 40 but fewer
249	     * than the hard limit of 50 owners) when this owner was created, flagging that the city is
250	     * approaching its capacity limit. Captured once at creation.
251	     */
252	    public Boolean getCapacityWarning() {
253	        return this.capacityWarning;
254	    }
255	
256	    public void setCapacityWarning(Boolean capacityWarning) {
257	        this.capacityWarning = capacityWarning;
258	    }
259	
260	    /**
261	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
262	     * counting this owner) captured once at creation.
263	     */
264	    public Integer getHouseholdSize() {
265	        return this.householdSize;
266	    }
267	
268	    public void setHouseholdSize(Integer householdSize) {
269	        this.householdSize = householdSize;
270	    }
271	
272	    /**
273	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
274	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
275	     */
276	    public String getPostcode() {
277	        return this.postcode;
278	    }
279	
280	    public void setPostcode(String postcode) {
281	        this.postcode = postcode;
282	    }
283	
284	    /**
285	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
286	     * creation, or {@code null} when none. Set at creation when an existing owner shares this
287	     * owner's {@code soundex(lastName)} and postcode but has a different {@link #getIdentityKey()
288	     * identity key} (e.g. a different telephone), so the two are not a hard duplicate. Captured
289	     * once at creation.
290	     */
291	    public Integer getPossibleDuplicateOf() {
292	        return this.possibleDuplicateOf;
293	    }
294	
295	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
296	        this.possibleDuplicateOf = possibleDuplicateOf;
297	    }
298	
299	    /**
300	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
301	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
302	     */
303	    @Transient
304	    public Boolean getPossibleDuplicate() {
305	        return this.possibleDuplicateOf != null;
306	    }
307	
308	    /**
309	     * Whether this owner warrants review, being {@code true} when any risk signal holds: the owner is
310	     * a {@link #getPossibleDuplicate() possible duplicate}, its email domain is
311	     * {@link DisposableEmailDomains#isDisposableAdjacent(String) disposable-adjacent}, or its city was
312	     * over its soft capacity (the {@link #getCapacityWarning() capacity-warning} band) when the owner
313	     * was created; otherwise {@code false}.
314	     */
315	    @Transient
316	    public Boolean getRiskFlag() {
317	        return getPossibleDuplicate()
318	            || Boolean.TRUE.equals(this.capacityWarning)
319	            || hasDisposableAdjacentEmail();
320	    }
321	
322	    /** Whether this owner's email domain is disposable-adjacent (see {@link DisposableEmailDomains}). */
323	    private boolean hasDisposableAdjacentEmail() {
324	        return DisposableEmailDomains.isDisposableAdjacent(DisposableEmailDomains.domainOf(this.email));
325	    }
326	
327	    /**
328	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
329	     * the highest membership level among the household members that already existed when this owner
330	     * was created, or {@code null} when the owner joined no existing household and is therefore
331	     * uncapped. Captured once at creation.
332	     */
333	    public Integer getMembershipLevelCap() {
334	        return this.membershipLevelCap;
335	    }
336	
337	    public void setMembershipLevelCap(Integer membershipLevelCap) {
338	        this.membershipLevelCap = membershipLevelCap;
339	    }
340	
341	    /**
342	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; deleting an owner
343	     * flags it {@code true} and retains the record rather than removing it. Duplicate and identity
344	     * checks at creation ignore owners flagged deleted.
345	     */
346	    public boolean isDeleted() {
347	        return this.deleted;
348	    }
349	
350	    public void setDeleted(boolean deleted) {
351	        this.deleted = deleted;
352	    }
353	
354	    /**
355	     * Return this owner's canonical API path, being {@code "/api/owners/"} followed by this owner's
356	     * {@link #getId() id}.
357	     */
358	    @Transient
359	    public String getSelfLink() {
360	        return "/api/owners/" + this.getId();
361	    }
362	
363	    /**
364	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
365	     */
366	    @Transient
367	    public String getDisplayName() {
368	        return this.getLastName() + ", " + this.getFirstName();
369	    }
370	
371	    /**
372	     * Return this owner's salutation as the {@link #getTitle() title} and last name separated by a
373	     * space (e.g. {@code "DR Who"}), or just the last name when no title was supplied.
374	     */
375	    @Transient
376	    public String getSalutation() {
377	        return (this.title == null || this.title.isBlank())
378	            ? this.getLastName()
379	            : this.title + " " + this.getLastName();
380	    }
381	
382	    /**
383	     * Return this owner's initials as the upper-cased first letters of the first and last
384	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
385	     */
386	    @Transient
387	    public String getInitials() {
388	        return initial(this.getFirstName()) + initial(this.getLastName());
389	    }
390	
391	    private static String initial(String name) {
392	        return Character.toUpperCase(name.charAt(0)) + ".";
393	    }
394	
395	    /** Points awarded when an email address is present. */
396	    private static final int EMAIL_POINTS = 2;
397	
398	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
399	    private static final int NO_NAMESAKE_POINTS = 1;
400	
401	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
402	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
403	
404	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
405	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
406	
407	    /** Points awarded for qualifying tenure. */
408	    private static final int TENURE_POINTS = 3;
409	
410	    /** The tenure, in elapsed fiscal years, that must be exceeded to earn {@link #TENURE_POINTS}. */
411	    private static final long MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS = 1;
412	
413	    /**
414	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
415	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
416	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
417	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
418	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed fiscal year since registration).
419	     */
420	    @Transient
421	    public Integer getMembershipPoints() {
422	        int points = 0;
423	        if (hasEmail()) {
424	            points += EMAIL_POINTS;
425	        }
426	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
427	            points += NO_NAMESAKE_POINTS;
428	        }
429	        if (hasLargeHousehold()) {
430	            points += LARGE_HOUSEHOLD_POINTS;
431	        }
432	        if (hasQualifyingTenure()) {
433	            points += TENURE_POINTS;
434	        }
435	        return points;
436	    }
437	
438	    /**
439	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
440	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then limited to the
441	     * owner's {@link #getMembershipLevelCap() membership-level ceiling} when one applies.
442	     */
443	    @Transient
444	    public Integer getMembershipLevel() {
445	        int level = membershipLevelFromPoints();
446	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
447	            return this.membershipLevelCap;
448	        }
449	        return level;
450	    }
451	
452	    /** Map this owner's {@link #getMembershipPoints() membership points} to the uncapped level. */
453	    private int membershipLevelFromPoints() {
454	        int points = getMembershipPoints();
455	        if (points <= 1) {
456	            return 1;
457	        }
458	        if (points <= 3) {
459	            return 2;
460	        }
461	        if (points <= 5) {
462	            return 3;
463	        }
464	        return 4;
465	    }
466	
467	    /**
468	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
469	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
470	     * qualify.
471	     */
472	    private boolean hasLargeHousehold() {
473	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
474	    }
475	
476	    /**
477	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed
478	     * fiscal year, i.e. more than that many fiscal years have elapsed between the fiscal year of the
479	     * {@code registrationDate} and the fiscal year of today. Owners without a registration date have
480	     * no measurable tenure and do not qualify.
481	     */
482	    private boolean hasQualifyingTenure() {
483	        if (this.registrationDate == null) {
484	            return false;
485	        }
486	        long elapsedFiscalYears = FiscalYear.of(this.registrationDate).yearsUntil(FiscalYear.of(LocalDate.now()));
487	        return elapsedFiscalYears > MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS;
488	    }
489	
490	    /** Whether this owner has a usable email address (present and not blank). */
491	    private boolean hasEmail() {
492	        return this.email != null && !this.email.isBlank();
493	    }
494	
495	    /**
496	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
497	     * present, otherwise {@code "PHONE"}.
498	     */
499	    @Transient
500	    public String getContactPreference() {
501	        return hasEmail() ? "EMAIL" : "PHONE";
502	    }
503	
504	    /**
505	     * Return this owner's age band derived from the {@code birthDate} as of the
506	     * {@code registrationDate}, or {@code null} when no birth date is known.
507	     */
508	    @Transient
509	    public AgeBand getAgeBand() {
510	        if (this.birthDate == null || this.registrationDate == null) {
511	            return null;
512	        }
513	        return AgeBand.asOf(this.birthDate, this.registrationDate);
514	    }
515	
516	    /**
517	     * Return this owner's locality: the region code resolved from the postcode (preferred, matched
518	     * against the known region ranges) falling back to the city-to-region table, or {@code "UNKNOWN"}
519	     * when neither yields a region. This is the same {@code <REGION>} segment that leads the owner's
520	     * {@link #getMemberId() member id}.
521	     */
522	    @Transient
523	    public String getLocality() {
524	        return LocalityResolver.regionFor(this.postcode, this.city);
525	    }
526	
527	    /**
528	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
529	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
530	     * known timezone.
531	     */
532	    @Transient
533	    public String getTimezone() {
534	        return LocalityResolver.timezoneFor(getLocality());
535	    }
536	
537	    /**
538	     * Return this owner's segment, formatted {@code <TIER>_<AREA>}: the tier is {@code PREMIUM} when
539	     * the {@link #getMembershipLevel() membership level} is 3 or more, otherwise {@code STANDARD};
540	     * the area is {@code METRO} when the {@link #getLocality() locality} is a known region (NSW, VIC
541	     * or QLD), otherwise {@code REGIONAL}.
542	     */
543	    @Transient
544	    public String getOwnerSegment() {
545	        return OwnerSegment.of(getMembershipLevel(), getLocality());
546	    }
547	
548	    /**
549	     * Return this owner's identity key, the single derived value all duplicate detection is based
550	     * on: the lower-case SHA-256 hex digest over {@code normalizedTelephone + "|" + lowerEmail +
551	     * "|" + soundex(lastName)}, with an absent email rendered as the empty string. Two owners are
552	     * duplicates only when their whole identity keys are equal; because the telephone is part of
553	     * the key, two owners with the same last name and postcode but different telephones have
554	     * distinct keys and are not duplicates (they are instead flagged as a soft match).
555	     */
556	    @Transient
557	    public String getIdentityKey() {
558	        String core = keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + Soundex.encode(this.getLastName());
559	        return Sha256Hex.lowerHex(core);
560	    }
561	
562	    private static String keyPart(String value) {
563	        return value == null ? "" : value;
564	    }
565	
566	    protected Set<Pet> getPetsInternal() {
567	        if (this.pets == null) {
568	            this.pets = new HashSet<>();
569	        }
570	        return this.pets;
571	    }
572	
573	    protected void setPetsInternal(Set<Pet> pets) {
574	        this.pets = pets;
575	    }
576	
577	    public List<Pet> getPets() {
578	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
579	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
580	        return Collections.unmodifiableList(sortedPets);
581	    }
582	
583	    public void setPets(List<Pet> pets) {
584	        this.pets = new HashSet<>(pets);
585	    }
586	
587	    public void addPet(Pet pet) {
588	        getPetsInternal().add(pet);
589	        pet.setOwner(this);
590	    }
591	
592	    /**
593	     * Return the Pet with the given name, or null if none found for this Owner.
594	     *
595	     * @param name to test
596	     * @return true if pet name is already in use
597	     */
598	    public Pet getPet(String name) {
599	        return getPet(name, false);
600	    }
601	
602	    /**
603	     * Return the Pet with the given name, or null if none found for this Owner.
604	     *
605	     * @param name to test
606	     * @return true if pet name is already in use
607	     */
608	    public Pet getPet(String name, boolean ignoreNew) {
609	        name = name.toLowerCase();
610	        for (Pet pet : getPetsInternal()) {
611	            if (!ignoreNew || !pet.isNew()) {
612	                String compName = pet.getName();
613	                compName = compName.toLowerCase();
614	                if (compName.equals(name)) {
615	                    return pet;
616	                }
617	            }
618	        }
619	        return null;
620	    }
621	
622	    public Pet getPet(Integer petId) {
623	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
624	    }
625	
626	    @Override
627	    public String toString() {
628	        return new ToStringCreator(this)
629	
630	            .append("id", this.getId())
631	            .append("new", this.isNew())
632	            .append("lastName", this.getLastName())
633	            .append("firstName", this.getFirstName())
634	            .append("address", this.address)
635	            .append("city", this.city)
636	            .append("telephone", this.telephone)
637	            .append("email", this.email)
638	            .append("registrationDate", this.registrationDate)
639	            .toString();
640	    }
641	}
