16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Locale;
22	
23	/**
24	 * Computes hexadecimal SHA-256 digests. Shared by the identifier generators and the owner
25	 * identity key so the digest-to-hex logic lives in exactly one place.
26	 */
27	public final class Sha256Hex {
28	
29	    private Sha256Hex() {
30	    }
31	
32	    /**
33	     * Digest {@code input} with SHA-256 and return its full hexadecimal representation in
34	     * lower case.
35	     *
36	     * @param input the string whose UTF-8 bytes are digested
37	     * @return the 64-character lower-case hexadecimal digest
38	     */
39	    public static String lowerHex(String input) {
40	        return fullHex(input);
41	    }
42	
43	    /**
44	     * Digest {@code input} with SHA-256 and return the first {@code length} characters of its
45	     * hexadecimal representation, upper-cased.
46	     *
47	     * @param input  the string whose UTF-8 bytes are digested
48	     * @param length the number of leading hex characters to return
49	     * @return the upper-case hexadecimal prefix of the digest
50	     */
51	    public static String upperHexPrefix(String input, int length) {
52	        return fullHex(input).substring(0, length).toUpperCase(Locale.ROOT);
53	    }
54	
55	    private static String fullHex(String input) {
56	        try {
57	            byte[] digest = MessageDigest.getInstance("SHA-256")
58	                .digest(input.getBytes(StandardCharsets.UTF_8));
59	            StringBuilder hex = new StringBuilder(digest.length * 2);
60	            for (byte b : digest) {
61	                hex.append(String.format("%02x", b));
62	            }
63	            return hex.toString();
64	        }
65	        catch (NoSuchAlgorithmException e) {
66	            throw new IllegalStateException("SHA-256 is required for identifier generation", e);
67	        }
68	    }
69	}
