16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Encodes a name with the <a href="https://en.wikipedia.org/wiki/Soundex">American Soundex</a>
20	 * phonetic algorithm, so names that sound alike share a code. The result is the retained first
21	 * letter followed by three digits (e.g. {@code "Robert"} and {@code "Rupert"} both encode to
22	 * {@code "R163"}). Used to group owners by how their last name sounds.
23	 */
24	public final class Soundex {
25	
26	    private Soundex() {
27	    }
28	
29	    /**
30	     * Encode {@code name} to its four-character Soundex code: the upper-cased first letter of the
31	     * name followed by three digits derived from the remaining consonants. Non-letter characters
32	     * are ignored; a value with no letters (or {@code null}) encodes to the empty string.
33	     *
34	     * @param name the name to encode
35	     * @return the four-character Soundex code, or the empty string when {@code name} has no letters
36	     */
37	    public static String encode(String name) {
38	        if (name == null) {
39	            return "";
40	        }
41	        StringBuilder letters = new StringBuilder();
42	        for (int i = 0; i < name.length(); i++) {
43	            char c = name.charAt(i);
44	            if (Character.isLetter(c)) {
45	                letters.append(Character.toUpperCase(c));
46	            }
47	        }
48	        if (letters.length() == 0) {
49	            return "";
50	        }
51	        StringBuilder code = new StringBuilder();
52	        code.append(letters.charAt(0));
53	        char previousCode = codeOf(letters.charAt(0));
54	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
55	            char c = letters.charAt(i);
56	            // 'h' and 'w' are transparent: they neither contribute a digit nor break the run of a
57	            // preceding consonant, so a same-coded consonant on either side still counts once.
58	            if (c == 'H' || c == 'W') {
59	                continue;
60	            }
61	            char digit = codeOf(c);
62	            if (digit != NO_CODE && digit != previousCode) {
63	                code.append(digit);
64	            }
65	            previousCode = digit;
66	        }
67	        while (code.length() < 4) {
68	            code.append('0');
69	        }
70	        return code.toString();
71	    }
72	
73	    /** The marker for letters (vowels, plus 'h' and 'w') that contribute no Soundex digit. */
74	    private static final char NO_CODE = '0';
75	
76	    private static char codeOf(char c) {
77	        switch (c) {
78	            case 'B': case 'F': case 'P': case 'V':
79	                return '1';
80	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
81	                return '2';
82	            case 'D': case 'T':
83	                return '3';
84	            case 'L':
85	                return '4';
86	            case 'M': case 'N':
87	                return '5';
88	            case 'R':
89	                return '6';
90	            default:
91	                return NO_CODE;
92	        }
93	    }
94	}
