16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Computes the <a href="https://en.wikipedia.org/wiki/Luhn_algorithm">Luhn</a> check digit over the
20	 * digits contained in a string. Non-digit characters are ignored, so the input may carry separators
21	 * or letters; only its decimal digits contribute.
22	 */
23	public final class LuhnCheckDigit {
24	
25	    private LuhnCheckDigit() {
26	    }
27	
28	    /**
29	     * Compute the Luhn check digit (0-9) over the digits contained in {@code s}, scanning
30	     * right-to-left and doubling every second digit starting with the rightmost.
31	     *
32	     * @param s the source whose decimal digits are checked; non-digit characters are ignored
33	     * @return the single check digit that, appended to the digits, makes the whole Luhn-valid
34	     */
35	    public static int of(String s) {
36	        int sum = 0;
37	        boolean doubleDigit = true;
38	        for (int i = s.length() - 1; i >= 0; i--) {
39	            char c = s.charAt(i);
40	            if (c < '0' || c > '9') {
41	                continue;
42	            }
43	            int d = c - '0';
44	            if (doubleDigit) {
45	                d *= 2;
46	                if (d > 9) {
47	                    d -= 9;
48	                }
49	            }
50	            sum += d;
51	            doubleDigit = !doubleDigit;
52	        }
53	        return (10 - (sum % 10)) % 10;
54	    }
55	}
