77	     * range), as opposed to {@link #UNKNOWN} or any other unrecognised value.
78	     *
79	     * @param region the region to test, or {@code null}
80	     * @return {@code true} when the region is a known region
81	     */
82	    public static boolean isKnownRegion(String region) {
83	        return region != null && REGION_RANGES.containsKey(region);
84	    }
