87	     * The IANA timezone name for the given region via the fixed region-to-timezone table.
88	     *
89	     * @param region the region to look up
90	     * @return the IANA timezone name, or {@code null} when the region has no known timezone
91	     */
92	    public static String timezoneFor(String region) {
93	        return REGION_TIMEZONES.get(region);
94	    }
95	
96	    /**
97	     * The inclusive four-digit postcode range for the given region.
98	     *
99	     * @param region the region to look up
100	     * @return a fresh {@code {low, high}} array, or {@code null} when the region has no range
101	     */
102	    public static int[] rangeForRegion(String region) {
103	        int[] range = REGION_RANGES.get(region);
104	        return range == null ? null : range.clone();
105	    }
106	
107	    /**
108	     * The region whose postcode range contains the given postcode.
109	     *
110	     * @param postcode the postcode to classify, or {@code null}/absent
111	     * @return the matching region, or {@code null} when the postcode is absent, not a number, or in
112	     *         no known range
113	     */
114	    private static String regionForPostcode(String postcode) {
115	        if (postcode == null) {
